entries[35695] = { ["name"] = "Design: Figurine - Empyrean Tortoise", ["text"] = "Binds when picked up\nUse: Teaches you how to create a Figurine - Empyrean Tortoise.\nRequires Outland Jewelcrafting (75)\nRequires Shattered Sun Offensive\n- Revered\nSell Price:\nFigurine - Empyrean Tortoise\nBinds when picked up\nUnique-Equipped\nTrinket\n+ 5 Dodge\nUse: Increases dodge by 24 for 20 sec. (2 Min Cooldown)\nRequires Outland Jewelcrafting (75)\nSell Price:\nRequires Khorium Bar (8), Empyrean Sapphire (2), Dawnstone (6)\nOptional Reagents: Optional Reagent Slot (#49)" }
entries[35696] = { ["name"] = "Design: Figurine - Khorium Boar", ["text"] = "Binds when picked up\nUse: Teaches you how to create a Figure - Khorium Boar.\nRequires Outland Jewelcrafting (75)\nRequires Shattered Sun Offensive\n- Revered\nSell Price:\nFigurine - Khorium Boar\nBinds when picked up\nUnique-Equipped\nTrinket\n+4 [Agility or Strength]\nUse: Summons the Khorium Boar to fight for you for 30 sec. (5 Min Cooldown)\nRequires Outland Jewelcrafting (75)\nSell Price:\nRequires Khorium Bar (8), Pyrestone (2), Primal Earth (8)\nOptional Reagents: Optional Reagent Slot (#49)" }
entries[35697] = { ["name"] = "Design: Figurine - Crimson Serpent", ["text"] = "Binds when picked up\nUse: Teaches you how to create a Figure - Crimson Serpent.\nRequires Outland Jewelcrafting (75)\nRequires Shattered Sun Offensive\n- Revered\nSell Price:\nFigurine - Crimson Serpent\nBinds when picked up\nUnique-Equipped\nTrinket\n+3 Intellect\n+4 Stamina\nUse: Increases spell power by 14 for 20 sec. (2 Min Cooldown)\nRequires Outland Jewelcrafting (75)\nSell Price:\nRequires Eternium Bar (8), Crimson Spinel (2), Primal Fire (8)\nOptional Reagents: Optional Reagent Slot (#49)" }
